package cloud.foxlin.aegir.security;
import java.nio.file.*;import java.time.Duration;import java.util.*;
public final class LegacySecurityScenario{
 private static void emit(String op,boolean ok){System.out.println(IntegrationJson.stringify(Map.of("op",op,"ok",ok)));}
 public static void main(String[]args){try{run(args);}catch(Exception failure){System.err.println("Legacy security scenario failed; no credential or upstream body logged.");System.exit(1);}}
 private static void run(String[]args)throws Exception{if(args.length!=1)throw new IllegalArgumentException("Private config path required.");Path file=Path.of(args[0]);if(Files.size(file)>32768)throw IntegrationJson.invalid();Map<String,Object>cfg=IntegrationJson.object(IntegrationJson.parse(Files.readString(file)));String api=IntegrationJson.string(cfg.get("apiBaseUrl"),2048),credential=IntegrationJson.string(cfg.get("developerKey"),2048),subject=IntegrationJson.string(cfg.get("subjectId"),512);Object pin=cfg.get("certificateSha256");Duration timeout=Duration.ofMillis(cfg.containsKey("timeoutMs")?IntegrationJson.integer(cfg.get("timeoutMs"),1):15000);try(AegirSecurityClient c=pin==null?new AegirSecurityClient(api,null,credential):AegirSecurityClient.pinnedLoopbackDevelopment(api,credential,IntegrationJson.string(pin,64),timeout,null)){c.scanIdentity(subject);emit("scan",true);c.getIdentityGraph(subject);emit("graph",true);c.getIdentityGraphJson(subject);emit("graphJson",true);c.getExposureSummary(subject);emit("exposure",true);SecurityModels.IdentityActionRecord record=c.performAction(new PerformIdentityActionRequest(subject,SecurityModels.IdentityActionType.RequestClarity,null,null));emit("performAction",true);c.reverseAction(record.getActionId(),null);emit("reverseAction",true);boolean found=false;for(SecurityModels.IdentityActionRecord item:c.getActionHistory(subject))if(record.getActionId().equals(item.getActionId())&&item.getStatus()==SecurityModels.IdentityActionStatus.Reversed)found=true;emit("history",found);if(!found)throw new IllegalStateException("Expected history absent.");}}
}
